# Kubernetes Pod Analysis Function

```python
import json
import re
from typing import List, Dict, Any, Tuple
from dataclasses import dataclass
from unittest import TestCase, main


@dataclass
class NodeMetrics:
    """Container for node resource metrics."""
    node_name: str
    pod_count: int
    cpu_request_millicores: float
    allocatable_cpu_millicores: float
    utilization_percentage: float
    is_over_90_percent: bool

    def to_dict(self) -> Dict[str, Any]:
        """Convert metrics to dictionary."""
        return {
            'node_name': self.node_name,
            'pod_count': self.pod_count,
            'cpu_request_millicores': self.cpu_request_millicores,
            'allocatable_cpu_millicores': self.allocatable_cpu_millicores,
            'utilization_percentage': round(self.utilization_percentage, 2),
            'is_over_90_percent': self.is_over_90_percent,
        }


def parse_cpu_value(cpu_str: str) -> float:
    """
    Parse Kubernetes CPU value to millicores.

    Handles formats:
    - '250m' -> 250 millicores
    - '1' -> 1000 millicores
    - '0.5' -> 500 millicores
    - '1.5' -> 1500 millicores
    - '100m' -> 100 millicores
    - None/empty -> 0

    Args:
        cpu_str: CPU value as string

    Returns:
        CPU in millicores as float

    Raises:
        ValueError: If the format is invalid
    """
    if not cpu_str or not isinstance(cpu_str, str):
        return 0.0

    cpu_str = cpu_str.strip()

    if not cpu_str:
        return 0.0

    # Handle millicores format (e.g., '250m')
    if cpu_str.endswith('m'):
        try:
            return float(cpu_str[:-1])
        except ValueError:
            raise ValueError(f"Invalid millicores format: {cpu_str}")

    # Handle decimal CPU format (e.g., '1', '0.5', '1.5')
    try:
        return float(cpu_str) * 1000
    except ValueError:
        raise ValueError(f"Invalid CPU format: {cpu_str}")


def analyze_pods(
    pods: List[Dict[str, Any]],
    allocatable_cpu_per_node: Dict[str, float] = None
) -> Dict[str, NodeMetrics]:
    """
    Analyze Kubernetes pods and aggregate metrics by node.

    Args:
        pods: List of Kubernetes pod JSON objects
        allocatable_cpu_per_node: Dictionary mapping node names to allocatable CPU in millicores.
                                 If None, uses a default of 4000m (4 CPU cores).

    Returns:
        Dictionary mapping node names to NodeMetrics objects

    Raises:
        ValueError: If pod structure is invalid or CPU values are malformed
        TypeError: If pods is not a list or contains non-dict items
    """
    if not isinstance(pods, list):
        raise TypeError("pods must be a list")

    if allocatable_cpu_per_node is None:
        allocatable_cpu_per_node = {}

    node_metrics: Dict[str, Dict[str, Any]] = {}
    default_allocatable = 4000.0  # Default to 4 cores = 4000 millicores

    for pod_idx, pod in enumerate(pods):
        if not isinstance(pod, dict):
            raise TypeError(f"Pod at index {pod_idx} is not a dictionary: {type(pod)}")

        # Extract node name from spec
        try:
            node_name = pod.get('spec', {}).get('nodeName')
            if not node_name:
                # Skip pods not yet scheduled
                continue
        except (AttributeError, TypeError) as e:
            raise ValueError(f"Invalid pod structure at index {pod_idx}: {e}")

        # Initialize node entry if not exists
        if node_name not in node_metrics:
            node_metrics[node_name] = {
                'pod_count': 0,
                'cpu_request_millicores': 0.0,
            }

        node_metrics[node_name]['pod_count'] += 1

        # Extract and sum CPU requests from all containers
        try:
            containers = pod.get('spec', {}).get('containers', [])
            if not isinstance(containers, list):
                raise ValueError(
                    f"Invalid containers format in pod at index {pod_idx}"
                )

            for container_idx, container in enumerate(containers):
                if not isinstance(container, dict):
                    raise TypeError(
                        f"Container {container_idx} in pod {pod_idx} is not a dict"
                    )

                requests = container.get('resources', {}).get('requests', {})
                cpu_request = requests.get('cpu')

                if cpu_request:
                    try:
                        parsed_cpu = parse_cpu_value(cpu_request)
                        node_metrics[node_name]['cpu_request_millicores'] += parsed_cpu
                    except ValueError as e:
                        raise ValueError(
                            f"Invalid CPU request in container {container_idx} "
                            f"of pod {pod_idx}: {e}"
                        )
        except (AttributeError, TypeError) as e:
            raise ValueError(f"Error processing pod at index {pod_idx}: {e}")

    # Build result with allocatable CPU information
    result: Dict[str, NodeMetrics] = {}

    for node_name, metrics in node_metrics.items():
        allocatable = allocatable_cpu_per_node.get(
            node_name,
            default_allocatable
        )

        if allocatable <= 0:
            raise ValueError(
                f"Invalid allocatable CPU for node {node_name}: {allocatable}"
            )

        utilization = (metrics['cpu_request_millicores'] / allocatable) * 100
        is_over_90 = utilization > 90.0

        result[node_name] = NodeMetrics(
            node_name=node_name,
            pod_count=metrics['pod_count'],
            cpu_request_millicores=metrics['cpu_request_millicores'],
            allocatable_cpu_millicores=allocatable,
            utilization_percentage=utilization,
            is_over_90_percent=is_over_90,
        )

    return result


