class TestParseCpuValue(TestCase):
    """Test CPU value parsing."""

    def test_parse_millicores(self):
        """Test parsing millicores format."""
        self.assertEqual(parse_cpu_value('250m'), 250.0)
        self.assertEqual(parse_cpu_value('1000m'), 1000.0)
        self.assertEqual(parse_cpu_value('100m'), 100.0)

    def test_parse_decimal_cpu(self):
        """Test parsing decimal CPU format."""
        self.assertEqual(parse_cpu_value('1'), 1000.0)
        self.assertEqual(parse_cpu_value('0.5'), 500.0)
        self.assertEqual(parse_cpu_value('1.5'), 1500.0)
        self.assertEqual(parse_cpu_value('2.25'), 2250.0)

    def test_parse_edge_cases(self):
        """Test edge cases."""
        self.assertEqual(parse_cpu_value(''), 0.0)
        self.assertEqual(parse_cpu_value(None), 0.0)
        self.assertEqual(parse_cpu_value('  '), 0.0)

    def test_parse_invalid_formats(self):
        """Test invalid formats."""
        with self.assertRaises(ValueError):
            parse_cpu_value('invalid')
        with self.assertRaises(ValueError):
            parse_cpu_value('250x')
        with self.assertRaises(ValueError):
            parse_cpu_value('m250')


